#include "wsoundspatial89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}
wsound89_result wsoundspatial89_init(wsoundspatial89_context*c,wsound89_i16*l,wsound89_i16*r,wsound89_u16 cap){wsound89_u16 i;if(!c||!l||!r||cap<2)return WSOUND89_EINVAL;c->left_delay=l;c->right_delay=r;c->capacity=cap;c->index=0;c->itd=0;c->pan_q15=0;c->far_low=0;c->shadow_q15=24000;for(i=0;i<cap;i++){l[i]=0;r[i]=0;}return WSOUND89_OK;}
void wsoundspatial89_set_azimuth(wsoundspatial89_context*c,wsound89_i16 pan,wsound89_u16 itd,wsound89_u16 shadow){if(!c)return;c->pan_q15=pan;c->itd=(itd<c->capacity)?itd:(wsound89_u16)(c->capacity-1U);c->shadow_q15=shadow;}
void wsoundspatial89_process_sample(wsoundspatial89_context*c,wsound89_i16 in,wsound89_i16*outl,wsound89_i16*outr){wsound89_u16 pos;wsound89_i32 nearv,farv,lg,rg;if(!c||!outl||!outr)return;c->left_delay[c->index]=in;c->right_delay[c->index]=in;pos=(wsound89_u16)((c->index+c->capacity-c->itd)%c->capacity);nearv=in;c->far_low+=(in-c->far_low)>>3;farv=(c->far_low*c->shadow_q15)>>15;if(c->pan_q15>=0){lg=32767-c->pan_q15;rg=32767;*outl=sat((c->left_delay[pos]*lg)>>15);*outr=sat((nearv*rg)>>15);}else{lg=32767;rg=32767+c->pan_q15;*outl=sat((nearv*lg)>>15);*outr=sat((c->right_delay[pos]*rg)>>15);}if(c->pan_q15>0)*outl=sat(((*outl)*3+farv)/4);else if(c->pan_q15<0)*outr=sat(((*outr)*3+farv)/4);c->index++;if(c->index>=c->capacity)c->index=0;}
